SELECT t.user_id, t.username, u.avatar, #{yearMonth} as stat_month, COALESCE(t.post_count, 0) as post_count, COALESCE(t.comment_count, 0) as comment_count, (COALESCE(t.post_count, 0) * 2 + COALESCE(t.comment_count, 0)) as total_score, @cur_rank := @cur_rank + 1 AS rank_position FROM ( SELECT p.user_id, u.username, COUNT(DISTINCT p.id) as post_count, ( SELECT COUNT(*) FROM comments c WHERE c.user_id = p.user_id AND DATE_FORMAT(c.created_at, '%Y-%m') = #{yearMonth} AND c.status = 1 ) as comment_count FROM posts p LEFT JOIN users u ON p.user_id = u.id WHERE DATE_FORMAT(p.created_at, '%Y-%m') = #{yearMonth} AND p.status = 1 GROUP BY p.user_id, u.username
UNION DISTINCT
SELECT c.user_id, u2.username, 0 as post_count, COUNT(*) as comment_count FROM comments c LEFT JOIN users u2 ON c.user_id = u2.id WHERE DATE_FORMAT(c.created_at, '%Y-%m') = #{yearMonth} AND c.status = 1 AND c.user_id NOT IN ( SELECT DISTINCT p2.user_id FROM posts p2 WHERE DATE_FORMAT(p2.created_at, '%Y-%m') = #{yearMonth} AND p2.status = 1 ) GROUP BY c.user_id, u2.username ) t LEFT JOIN users u ON t.user_id = u.id CROSS JOIN (SELECT @cur_rank := 0) r ORDER BY total_score DESC, post_count DESC LIMIT #{limit}
